#!/usr/bin/env bash
set -euo pipefail
dr_root="$(mktemp -d "${RUNNER_TEMP:-/tmp}/ouf-ingestion-dr.XXXXXX")"
evidence="${GITHUB_WORKSPACE:-$(pwd)}/target/dr-evidence";mkdir -p "$evidence"
primary=ingestion-dr-primary;restored=ingestion-dr-restored;password=dr-ci-password;app_pid=""
cleanup(){ [[ -z "$app_pid" ]] || kill "$app_pid" 2>/dev/null || true;docker rm -f "$primary" "$restored" >/dev/null 2>&1 || true; }
trap cleanup EXIT
wait_db(){ for attempt in $(seq 1 60);do if docker exec -e PGPASSWORD="$password" "$1" psql -U ouf_ingestion -d ouf_ingestion -Atc 'select 1' 2>/dev/null | grep -qx 1;then return 0;fi;sleep 1;done;docker logs "$1";return 1; }
wait_http(){ for attempt in $(seq 1 60);do curl --fail --silent "$1" >/dev/null&&return 0;sleep 1;done;return 1; }
docker run -d --name "$primary" -p 55442:5432 -e POSTGRES_DB=ouf_ingestion -e POSTGRES_USER=ouf_ingestion -e POSTGRES_PASSWORD="$password" postgres:17-alpine >/dev/null
wait_db "$primary"
OUF_ING_DB_URL='jdbc:postgresql://127.0.0.1:55442/ouf_ingestion' OUF_ING_DB_USER=ouf_ingestion OUF_ING_DB_PASSWORD="$password" java -jar target/ingestion-runtime-*.jar --server.port=18083 >"$evidence/primary.log" 2>&1 & app_pid="$!"
wait_http http://127.0.0.1:18083/actuator/health/readiness;kill "$app_pid";wait "$app_pid" 2>/dev/null||true;app_pid=""
docker exec -e PGPASSWORD="$password" "$primary" psql -U ouf_ingestion -d ouf_ingestion -v ON_ERROR_STOP=1 -c "insert into ouf_ingestion.ing_run(run_id,source_id,bundle_id,bundle_version,bundle_checksum,mode,state,correlation_id) values('10000000-0000-0000-0000-000000000001','dr-source','dr-bundle','1','sha256:dr','MANAGED_ONCE','RUNNING','dr-correlation');insert into ouf_ingestion.ing_partition(run_id,partition_key,state) values('10000000-0000-0000-0000-000000000001','default','RUNNING');insert into ouf_ingestion.runtime_configuration_snapshot(snapshot_id,run_id,bundle_id,bundle_version,bundle_checksum,snapshot_json) values('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','dr-bundle','1','sha256:dr','{}');insert into ouf_ingestion.processing_attempt(attempt_id,run_id,source_object_id,attempt_no,adapter_id,bundle_version,state) values('30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','object-1',1,'dr-adapter','1','SUCCEEDED');insert into ouf_ingestion.ing_lineage(lineage_id,run_id,attempt_id,source_object_id,bundle_ref,adapter_ref,evidence_json) values('40000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','object-1','dr-bundle:1','dr-adapter','{}');insert into ouf_ingestion.handoff_outbox(handoff_id,run_id,lineage_id,idempotency_key,payload_json,sequence_no,candidate_watermark_json) values('50000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','dr-idempotency','{}',1,'{\"ordinal\":1}');insert into ouf_ingestion.ing_watermark(source_id,partition_key,watermark_json,committed_handoff_id) values('dr-source','default','{\"ordinal\":0}','50000000-0000-0000-0000-000000000001');insert into ouf_ingestion.ing_quarantine(quarantine_id,run_id,attempt_id,reason_code,evidence_ref,correlation_id) values('60000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','ING_DR_FIXTURE','evidence:dr','dr-correlation');" >/dev/null
docker exec -e PGPASSWORD="$password" "$primary" pg_dump -U ouf_ingestion -d ouf_ingestion -Fc -f /tmp/ingestion.dump
docker cp "$primary:/tmp/ingestion.dump" "$dr_root/ingestion.dump"
docker run -d --name "$restored" -p 55443:5432 -e POSTGRES_DB=ouf_ingestion -e POSTGRES_USER=ouf_ingestion -e POSTGRES_PASSWORD="$password" postgres:17-alpine >/dev/null
wait_db "$restored";docker cp "$dr_root/ingestion.dump" "$restored:/tmp/ingestion.dump";docker exec -e PGPASSWORD="$password" "$restored" pg_restore -U ouf_ingestion -d ouf_ingestion --clean --if-exists /tmp/ingestion.dump
validation="$(docker exec -e PGPASSWORD="$password" "$restored" psql -U ouf_ingestion -d ouf_ingestion -Atc "select (select count(*) from ouf_ingestion.runtime_configuration_snapshot)||':'||(select count(*) from ouf_ingestion.ing_run where state='RUNNING')||':'||(select count(*) from ouf_ingestion.ing_watermark)||':'||(select count(*) from ouf_ingestion.ing_quarantine)||':'||(select count(*) from ouf_ingestion.handoff_outbox where state='READY')")"
[[ "$validation" == "1:1:1:1:1" ]]
OUF_ING_DB_URL='jdbc:postgresql://127.0.0.1:55443/ouf_ingestion' OUF_ING_DB_USER=ouf_ingestion OUF_ING_DB_PASSWORD="$password" java -jar target/ingestion-runtime-*.jar --server.port=18084 >"$evidence/restored.log" 2>&1 & app_pid="$!"
wait_http http://127.0.0.1:18084/actuator/health/readiness
printf 'result=PASS\npostgres=17\nrestored=config_snapshot,open_run,watermark,quarantine,ready_handoff\nvalidation=%s\n' "$validation" >"$evidence/DR_RESULT.txt"
(cd "$evidence"&&sha256sum DR_RESULT.txt primary.log restored.log >SHA256SUMS)
